-- Sincronizar textos de comunidad y provincia en anuncios ya existentes
UPDATE anuncios a, comunidades c, provincias p
SET a.comunidad_autonoma = c.nombre, a.provincia = p.nombre
WHERE a.comunidad_id = c.id AND a.provincia_id = p.id;

